CREATE TABLE IF NOT EXISTS instruments (id INTEGER PRIMARY KEY AUTOINCREMENT, symbol TEXT NOT NULL UNIQUE, name TEXT NOT NULL, exchange TEXT NOT NULL DEFAULT '', market TEXT NOT NULL DEFAULT '', currency TEXT NOT NULL DEFAULT 'USD', timezone TEXT NOT NULL DEFAULT 'America/New_York', data_provider TEXT NOT NULL DEFAULT 'mock', provider_symbol TEXT NOT NULL, price_adjustment TEXT NOT NULL DEFAULT 'splits' CHECK(price_adjustment IN ('raw','splits')), market_data_stale INTEGER NOT NULL DEFAULT 0, last_market_refresh_at TEXT, exit_fee_rate_pct TEXT NOT NULL DEFAULT '0', exit_fee_fixed TEXT NOT NULL DEFAULT '0', exit_fee_minimum TEXT NOT NULL DEFAULT '0', created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS candles (id INTEGER PRIMARY KEY AUTOINCREMENT, instrument_id INTEGER NOT NULL REFERENCES instruments(id) ON DELETE CASCADE, interval TEXT NOT NULL DEFAULT '1day', timestamp TEXT NOT NULL, open REAL NOT NULL, high REAL NOT NULL, low REAL NOT NULL, close REAL NOT NULL, volume REAL NOT NULL, source TEXT NOT NULL DEFAULT 'mock', adjustment TEXT NOT NULL DEFAULT 'raw', created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE UNIQUE INDEX IF NOT EXISTS candles_instrument_interval_timestamp_adjustment ON candles(instrument_id, interval, timestamp, adjustment);
CREATE INDEX IF NOT EXISTS candles_instrument_timestamp ON candles(instrument_id, timestamp);
CREATE TABLE IF NOT EXISTS strategies (id INTEGER PRIMARY KEY AUTOINCREMENT, name TEXT NOT NULL UNIQUE, description TEXT NOT NULL DEFAULT '', created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS trades (id INTEGER PRIMARY KEY AUTOINCREMENT, instrument_id INTEGER NOT NULL REFERENCES instruments(id) ON DELETE CASCADE, account_id INTEGER NOT NULL DEFAULT 1, side TEXT NOT NULL CHECK(side IN ('BUY','SELL')), trade_at TEXT NOT NULL, trade_date TEXT NOT NULL, price TEXT NOT NULL, quantity TEXT NOT NULL, fee TEXT NOT NULL DEFAULT '0', estimated_exit_fee TEXT NOT NULL DEFAULT '0', currency TEXT NOT NULL, strategy_id INTEGER REFERENCES strategies(id) ON DELETE SET NULL, reason TEXT NOT NULL DEFAULT '', plan TEXT NOT NULL DEFAULT '', note TEXT NOT NULL DEFAULT '', planned_stop TEXT, planned_target TEXT, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX IF NOT EXISTS trades_instrument_date ON trades(instrument_id, trade_date);
CREATE INDEX IF NOT EXISTS trades_side ON trades(side);
CREATE TABLE IF NOT EXISTS tags (id INTEGER PRIMARY KEY AUTOINCREMENT, name TEXT NOT NULL UNIQUE, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS trade_tags (trade_id INTEGER NOT NULL REFERENCES trades(id) ON DELETE CASCADE, tag_id INTEGER NOT NULL REFERENCES tags(id) ON DELETE CASCADE);
CREATE UNIQUE INDEX IF NOT EXISTS trade_tags_unique ON trade_tags(trade_id, tag_id);
CREATE TABLE IF NOT EXISTS manual_levels (id INTEGER PRIMARY KEY AUTOINCREMENT, instrument_id INTEGER NOT NULL REFERENCES instruments(id) ON DELETE CASCADE, price REAL NOT NULL, type TEXT NOT NULL CHECK(type IN ('SUPPORT','RESISTANCE','CUSTOM')), label TEXT NOT NULL DEFAULT '', start_date TEXT, end_date TEXT, note TEXT NOT NULL DEFAULT '', created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS trade_analysis_snapshots (id INTEGER PRIMARY KEY AUTOINCREMENT, trade_id INTEGER NOT NULL UNIQUE REFERENCES trades(id) ON DELETE CASCADE, analysis_version TEXT NOT NULL, price REAL NOT NULL, range_20_high REAL, range_20_low REAL, range_20_percentile REAL, range_60_high REAL, range_60_low REAL, range_60_percentile REAL, range_120_high REAL, range_120_low REAL, range_120_percentile REAL, range_250_high REAL, range_250_low REAL, range_250_percentile REAL, ma_5 REAL, ma_10 REAL, ma_20 REAL, ma_60 REAL, ma_120 REAL, ma_250 REAL, distance_to_ma_20_pct REAL, distance_to_ma_60_pct REAL, atr_14 REAL, atr_percent REAL, volume REAL, avg_volume_20 REAL, volume_ratio_20 REAL, nearest_prior_pivot_high REAL, distance_to_pivot_high_pct REAL, pivot_high_date TEXT, nearest_prior_pivot_low REAL, distance_to_pivot_low_pct REAL, pivot_low_date TEXT, days_since_20_high INTEGER, days_since_20_low INTEGER, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS trade_outcomes (id INTEGER PRIMARY KEY AUTOINCREMENT, trade_id INTEGER NOT NULL UNIQUE REFERENCES trades(id) ON DELETE CASCADE, return_1d REAL, return_3d REAL, return_5d REAL, return_10d REAL, return_20d REAL, return_60d REAL, mfe_5d REAL, mae_5d REAL, mfe_20d REAL, mae_20d REAL, max_high_20d REAL, min_low_20d REAL, sell_missed_gain_20d REAL, buy_validation_score REAL, calculated_through TEXT, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
